sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
      /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
      /* Optional GlideRecord */ event) {
      var gr = new GlideRecord('x_2145749_qc_fraud_flag');
      gr.addQuery('refund_request', current.sys_id);
      gr.query();
      if (gr.getRowCount() === 0) {
        template.print('<p><em>No individual fraud flags recorded yet.</em></p>');
      } else {
        template.print('<ul>');
        while (gr.next()) {
          template.print('<li><strong>' + gr.getDisplayValue('rule_name') + '</strong> (weight ' + gr.getValue('risk_weight') + '): ' + gr.getValue('details') + '</li>');
        }
        template.print('</ul>');
      }
})(current, template, email, email_action, event);
